import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong univariate predictors (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features for now
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if p_val < 0.01:
            strong_features.append((fid, abs(t_stat)))

    # Sort by effect size
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated with |r| >= 0.6)
    to_remove = set()
    correlations = {}
    for a in feats.ids:
        for b in feats.ids:
            if a >= b:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(a)], feats.x[:, feats.column(b)])[0,1]
            if abs(corr) >= 0.6:
                correlations[(a,b)] = corr

    for a, b in correlations:
        if a in [f[0] for f in strong_features] and b in [f[0] for f in strong_features]:
            # Remove the one with smaller effect size
            fa = None
            fb = None
            for f in strong_features:
                if f[0] == a:
                    fa = f
                elif f[0] == b:
                    fb = f
            if fa and fb:
                if fa[1] < fb[1]:
                    to_remove.add(a)
                else:
                    to_remove.add(b)

    # Filter out near-duplicates
    strong_features = [f for f in strong_features if f[0] not in to_remove]

    # Select top drivers
    drivers = tuple(f[0] for f in strong_features[:MAX_DRIVERS])

    # Build columns list (all features with significant univariate associations)
    columns = tuple(f[0] for f in strong_features if f[0] not in to_remove)

    # Check for interaction terms (product features)
    products = []
    for i, a in enumerate(columns):
        for b in columns[i+1:]:
            # Compute correlation between products
            prod_a_b = feats.x[:, feats.column(a)] * feats.x[:, feats.column(b)]
            y_corr = np.abs(np.corrcoef(prod_a_b, feats.y)[0,1])
            if y_corr > 0.05:
                products.append((a, b))

    # Weighted score based on univariate effects
    loadings = {}
    for fid, _ in strong_features[:MAX_DRIVERS]:
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, feats.column(fid)], 
                                   feats.x[feats.y==0, feats.column(fid)])
        loadings[fid] = t_stat

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

